// ============================================================
// CREDO HR-Portal — E-Mail an neuen Mitarbeiter
// Personalfragebogen-Link zusenden
// ============================================================

const CONFIG = {
  debugMode: false,
  senderName: 'CREDO Personalverwaltung',
  senderEmail: 'personal@credo-gruppe.de'
};

try {
  const item = $input.first().json;
  const { fragebogenLink, displayId, email, organization, mandantNumber, tokenExpiresAt } = item.body || item;

  if (!fragebogenLink || !email) {
    throw new Error(`Pflichtfelder fehlen: fragebogenLink=${!!fragebogenLink}, email=${!!email}`);
  }

  const expiryDate = tokenExpiresAt
    ? new Date(tokenExpiresAt).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : '30 Tage nach Erstellung';

  const orgName = organization || 'CREDO';

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <!-- Header -->
  <tr><td style="background-color:#005d6a;padding:30px 40px;text-align:center;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:28px;margin:0;letter-spacing:2px;">CREDO</h1>
    <p style="color:#ffffff;font-size:12px;margin:5px 0 0;letter-spacing:3px;">Glauben &bull; Leben &bull; Gemeinsam</p>
  </td></tr>
  <!-- Body -->
  <tr><td style="padding:40px;">
    <h2 style="color:#005d6a;font-size:20px;margin:0 0 20px;">Willkommen bei ${orgName}!</h2>
    <p style="color:#333333;font-size:15px;line-height:1.6;margin:0 0 15px;">Sehr geehrte/r neue/r Mitarbeiter/in,</p>
    <p style="color:#333333;font-size:15px;line-height:1.6;margin:0 0 15px;">wir freuen uns, Sie bald in unserem Team begruessen zu duerfen! Im Rahmen Ihres Einstellungsprozesses bitten wir Sie, den digitalen Personalfragebogen auszufuellen.</p>
    <p style="color:#333333;font-size:15px;line-height:1.6;margin:0 0 5px;"><strong>Vorgang:</strong> ${displayId || 'k.A.'}</p>
    <p style="color:#333333;font-size:15px;line-height:1.6;margin:0 0 5px;"><strong>Einrichtung:</strong> ${orgName}</p>
    <p style="color:#333333;font-size:15px;line-height:1.6;margin:0 0 25px;"><strong>Gueltig bis:</strong> ${expiryDate}</p>
    <!-- CTA Button -->
    <table cellpadding="0" cellspacing="0" style="margin:0 auto 25px;">
    <tr><td align="center" style="background-color:#005d6a;border-radius:6px;">
      <a href="${fragebogenLink}" target="_blank" style="display:inline-block;padding:14px 40px;color:#ffffff;font-size:16px;font-weight:bold;text-decoration:none;">Fragebogen oeffnen</a>
    </td></tr>
    </table>
    <p style="color:#666666;font-size:13px;line-height:1.5;margin:0 0 10px;">Falls der Button nicht funktioniert, kopieren Sie diesen Link in Ihren Browser:</p>
    <p style="color:#005d6a;font-size:13px;line-height:1.5;word-break:break-all;margin:0 0 25px;">${fragebogenLink}</p>
    <hr style="border:none;border-top:1px solid #eeeeee;margin:25px 0;">
    <p style="color:#666666;font-size:13px;line-height:1.5;margin:0;">Ihre Daten werden verschluesselt uebertragen und gemaess DSGVO verarbeitet. Bei Fragen wenden Sie sich an <a href="mailto:personal@credo-gruppe.de" style="color:#005d6a;">personal@credo-gruppe.de</a>.</p>
  </td></tr>
  <!-- CREDO-Linie -->
  <tr><td style="padding:0;">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      <td width="50%" style="height:4px;background-color:#DADADA;"></td>
      <td width="12.5%" style="height:4px;background-color:#FBC900;"></td>
      <td width="12.5%" style="height:4px;background-color:#6BAA24;"></td>
      <td width="12.5%" style="height:4px;background-color:#E2001A;"></td>
      <td width="12.5%" style="height:4px;background-color:#009AC6;"></td>
    </tr></table>
  </td></tr>
  <!-- Footer -->
  <tr><td style="background-color:#f9f9f9;padding:20px 40px;text-align:center;">
    <p style="color:#999999;font-size:11px;line-height:1.5;margin:0;">Christlicher Schulverein Minden e.V. &middot; Kingsleyallee 6 &middot; 32425 Minden<br>Tel. 0571 388 60-148 &middot; <a href="https://fes-minden.de" style="color:#005d6a;text-decoration:none;">fes-minden.de</a></p>
  </td></tr>
</table>
</td></tr>
</table>
</body></html>`;

  if (CONFIG.debugMode) {
    console.log(`[onboarding-created] E-Mail an ${email}, Vorgang ${displayId}`);
  }

  return [{
    json: {
      to: email,
      subject: `Ihr Personalfragebogen — ${orgName} (${displayId || ''})`,
      html: htmlBody
    }
  }];

} catch (error) {
  console.error('[onboarding-created] Fehler:', error.message);
  return [{ json: { error: error.message, event: 'onboarding-created' } }];
}

// ============================================================
// CREDO HR-Portal — E-Mail an Vorgesetzten
// Modalitaeten-Link zusenden
// ============================================================

const CONFIG = {
  debugMode: false
};

try {
  const item = $input.first().json;
  const { modalitaetenLink, supervisorEmail, employeeName, organization, mandantNumber, tokenExpiresAt } = item.body || item;

  if (!modalitaetenLink || !supervisorEmail) {
    throw new Error(`Pflichtfelder fehlen: modalitaetenLink=${!!modalitaetenLink}, supervisorEmail=${!!supervisorEmail}`);
  }

  const expiryDate = tokenExpiresAt
    ? new Date(tokenExpiresAt).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : '30 Tage nach Erstellung';

  const orgName = organization || 'CREDO';
  const empName = employeeName || 'neue/r Mitarbeiter/in';

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <tr><td style="background-color:#005d6a;padding:30px 40px;text-align:center;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:28px;margin:0;letter-spacing:2px;">CREDO</h1>
    <p style="color:#ffffff;font-size:12px;margin:5px 0 0;letter-spacing:3px;">Glauben &bull; Leben &bull; Gemeinsam</p>
